glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
#if ENABLE_GAUSSIAN_BLUR
layout(std140) uniform GaussianBlur {
  vec2 textureSize;
};
#endif
#if USE_WAVE
layout(std140) uniform Constant {
  vec4 waveFactor;
  float waveFrequency;
  float waveAmplitude;
};
#endif
#if USE_ALPHA_TEST
layout(std140) uniform ALPHA_TEST_DATA {
  float alphaThreshold;
};
#endif
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
#define iResolution cc_screenSize
in vec4 color;
#if USE_WAVE
#endif
#if ENABLE_GAUSSIAN_BLUR
  float getWeight(float x, float y) {
    return (1.0 / (2.0 * 3.141592653589793 * pow(1.5, 2.0))) * pow(1.0 / 2.718281828459045, (pow(x, 2.0) + pow(y, 2.0)) / (2.0 * pow(1.5, 2.0)));
  }
#endif
#if USE_TEXTURE
  in vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
vec2 waveOffset (in vec2 uv0) {
     float waveWidth = 0.1;
    vec2 uv = uv0;
    #if USE_WAVE
      vec2 clickPos = vec2(waveFactor.x-uv0.x,waveFactor.y-uv0.y);
      float dis = sqrt(clickPos.y * clickPos.y+clickPos.x*clickPos.x);
      float discardFactor = clamp(waveWidth - abs(waveFactor.w - dis), 0.0, 1.0)/waveWidth;
      float sinFactor =  sin(dis * waveFrequency + waveFactor.z * 10.0) * waveAmplitude;
      vec2 offset = normalize(clickPos) * sinFactor * discardFactor;
      uv += offset;
    #endif
    return uv;
}
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    vec2 uv = waveOffset(uv0);
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv);
    #if IS_GRAY
      float gray  = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
  #endif
  o *= color;
  ALPHA_TEST(o);
  #if ENABLE_GAUSSIAN_BLUR
    const highp float size = floor(1.5 * 6.0 + 1.0);
    const highp float halfSize = floor(size / 2.0);
    float totalWeight = getWeight(0.0, 0.0);
    for(float x = 1.0; x <= halfSize; x++) {
        totalWeight += getWeight(x, 0.0) * 2.0;
    }
    for(float y = 1.0; y <= halfSize; y++) {
        totalWeight += getWeight(0.0, y) * 2.0;
    }
    for(float x = 1.0; x <= halfSize; x++) {
      for (float y = 1.0; y<= halfSize; y++) {
        totalWeight += getWeight(x, y) * 4.0;
      }
    }
    vec4 finalColor = vec4(0.0, 0.0, 0.0, 0.0);
    float onePxWidth = 1.0 / textureSize.x;
    float onePxHeight = 1.0 / textureSize.y;
    for(float x = -halfSize; x<= halfSize; x++) {
      for (float y = -halfSize; y<= halfSize; y++) {
        float weight = getWeight(x, y) / totalWeight;
        finalColor += CCSampleWithAlphaSeparated(cc_spriteTexture, uv + vec2(onePxWidth * x, onePxHeight * y)) * weight;
      }
    }
    o = finalColor;
  #endif
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

